def binary_search(arr: list, target: int) -> int:
    """targetが見つかった場合はそのインデックス、なければ-1を返します。"""
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
```

